import { icon, sprite } from './art.js';
import { characterSprite } from './characters.js';
import { shelterAnimals, shelterHomes, shelterProjects, observatoryProjects } from './haven-content.js';
import { skyConditions, splitSky, homeSuitable } from './haven-model.js';
import { neighbourUnlocked, lockReason } from './neighbour-model.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(action,label,id='',disabled=false)=>`<button class="button outline" data-neighbour="${action}" data-id="${esc(id)}" ${disabled?'disabled':''}>${label}</button>`;
const top=title=>`<div class="dialog-top"><span class="eyebrow">${title}</span><button class="icon-button" data-neighbour="close" aria-label="Close">${icon('close')}</button></div>`;
const list=(state,projects)=>`<ol class="neighbour-project-list">${projects.map(p=>{const done=state.neighbours.completed.includes(p.id),ready=neighbourUnlocked(state,p);return `<li><span class="lesson-knot ${done?'done':''}">${icon(done?'check':ready?'code':'lock')}</span><div><strong>${p.title}</strong><small>${done?'Made together. Revisit or run your saved tool.':ready?`${p.xp} XP · ${p.coins} coins`:esc(lockReason(state,p))}</small></div>${btn('project',done?'Revisit':'Begin',p.id,!ready)}${done?btn('use','Run',p.id):''}</li>`;}).join('')}</ol>`;
export function animalArt(a){
  return `<span class="haven-animal-art haven-companion-sprite ${a.id}">${sprite(a.id)}</span>`;
}
function adoptionMarkup(state,a){
  const helped=state.neighbours.completed.includes(a.helpProject),owned=state.owned.includes(a.id),equipped=state.equipped===a.id,short=Math.max(0,a.cost-state.coins);
  if(owned)return `<div class="haven-adoption"><p>${a.name} has a home with you. Bring your friend along to the village, your room, or the learning trail.</p>${btn('adopt-companion',equipped?'Already by your side':'Bring '+a.name+' along',a.id,equipped)}<a href="#companions">Play and settle in together</a></div>`;
  return `<div class="haven-adoption"><p>${helped?`${a.name} is ready for a new adventure. Rowan will put the adoption coins toward blankets and supplies for the next visitor.`:`Help ${a.name} with <strong>${a.helpTitle}</strong> to prepare a travelling nest.`}</p>${helped?btn('adopt-companion',short?`${short} more coins needed`:`Adopt ${a.name} for ${a.cost} coins`,a.id,short>0):btn('project','Help '+a.name+' · '+a.helpTitle,a.helpProject)}<small>${helped?`${state.coins} coins in your purse · ${a.cost} coins to adopt`:`${a.cost} coins to adopt after helping · ${a.required?a.required+' trail quests needed':'Available from the beginning'}`}</small></div>`;
}
export function telescopeArt(ready){
  return `<svg class="haven-telescope ${ready?'restored':''}" viewBox="0 0 300 360" aria-hidden="true"><defs><linearGradient id="scope-brass" x2="0" y2="1"><stop stop-color="#fff0b7"/><stop offset=".3" stop-color="#bb8541"/><stop offset=".65" stop-color="#f2cc7c"/><stop offset="1" stop-color="#79522e"/></linearGradient></defs><ellipse cx="150" cy="342" rx="130" ry="13" fill="#211e25" opacity=".35"/><path d="M150 175L50 337M150 175L250 337M150 175L157 344" stroke="#49382c" stroke-width="15"/><path d="M150 175L50 337M150 175L250 337M150 175L157 344" stroke="#be8b53" stroke-width="7"/><circle cx="150" cy="175" r="22" fill="url(#scope-brass)" stroke="#64482e" stroke-width="3"/><path d="M150 167v-45" stroke="#e3bc76" stroke-width="12"/><g transform="rotate(-28 150 100)"><rect x="47" y="69" width="204" height="60" rx="5" fill="url(#scope-brass)" stroke="#6b4e31" stroke-width="3"/><path d="M62 68v62m165-62v62" stroke="#805932" stroke-width="7"/><rect x="25" y="85" width="23" height="28" fill="#b28a57"/><ellipse cx="252" cy="99" rx="11" ry="30" fill="#264d59" stroke="#edce85" stroke-width="5"/><ellipse cx="252" cy="90" rx="4" ry="13" fill="#92bac2" opacity=".6"/></g>${!ready?'<path d="M36 55Q160 26 262 63L265 200 215 190 190 225 84 199 30 207Z" fill="#586e68" stroke="#a99b7e" stroke-width="3"/><path d="M80 64l4 132m57-145 8 148m68-136-2 127" stroke="#304b46" opacity=".5" stroke-width="4"/>':''}</svg>`;
}
export function renderHaven(state,view,pet){
  const shelter=view==='shelter',n=state.neighbours,projects=shelter?shelterProjects:observatoryProjects,done=projects.filter(p=>n.completed.includes(p.id)).length,ready=n.completed.includes('sky-focus'),last=n.skyObservations.at(-1);
  return `<section class="neighbours-root neighbours-world haven-world" data-view="${view}"><header class="court-heading"><div><p class="eyebrow">${shelter?'ROWAN’S OPEN DOOR':'ON THE HILL ABOVE WILLOWMERE'}</p><h1>${shelter?'The companion haven':'Elio’s observatory'}</h1><p>${shelter?'A blanket, a bowl, and time to feel at home.':'Some questions are better with cocoa and company.'} ${done}/${projects.length} projects made together.</p></div><a class="button outline" href="#${shelter?'companions':'lake'}">${shelter?'Companion garden':'Down to the lake'}</a></header><div class="haven-stage"><div class="haven-scene ${view}-scene"><img class="neighbour-backdrop" src="assets/${shelter?'companion-haven':'willowmere-observatory'}.png" alt="${shelter?'A lamplit cottage with woven animal beds, folded blankets and an open door to Hearthwick':'A warm copper-domed observatory above the lantern-lit lake'}"><span class="haven-glow" aria-hidden="true"></span>${shelter?shelterAnimals.map((a,i)=>`<button class="haven-resident resident-${i}" data-neighbour="animal" data-id="${a.id}" aria-label="Visit ${a.name}">${animalArt(a)}<span>${a.name}${state.owned.includes(a.id)?' · your friend':n.completed.includes(a.helpProject)?' · ready to adopt':' · needs a hand'}</span></button>`).join(''):`<button class="telescope-object" data-neighbour="${ready?'sky-journal':'project'}" data-id="sky-focus" aria-label="${ready?'Open your sky journal':'Restore Elio’s telescope'}">${telescopeArt(ready)}<span>${ready?'The Lantern Star journal':'Uncover an old memory'}</span></button>`}<span class="haven-host">${characterSprite(shelter?'rowan':'elio')}<span class="court-pet">${shelter&&shelterAnimals.some(a=>a.id===pet.id)?'':sprite(pet.id)}</span></span><p class="haven-scene-note" role="status">${shelter?(n.completed.includes('shelter-round')?'Nell takes the morning round; Rowan comes after closing.':'Rowan has kept a chair for you beside the baskets.'):(last?`Visit ${last.id} · ${esc(last.sky)} sky · brightness ${last.brightness} fictional units`:'Elio turns the key. “I think June would like us to begin again.”')}</p></div></div><div class="haven-controls">${shelter?`${btn('shelter-book','Sit with Rowan · care ledger')}<span>${shelterAnimals.filter(a=>state.owned.includes(a.id)).length}/3 haven friends welcomed · help, then adopt</span>`:`<label>Imagine the sky <select id="haven-sky">${skyConditions.map(s=>`<option value="${s}" ${n.sky===s?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></label>${btn('observe-sky','Look through the telescope','',!ready)}${btn('sky-journal','Open the journal')}<span>${n.skyObservations.length} observations · no waiting</span>`}</div><p class="neighbour-status sr-only" role="status"></p></section>`;
}
export function havenBook(state,view){
  const n=state.neighbours;
  if(view==='shelter')return `${top('THE OPEN-DOOR CARE LEDGER')}<h2>A little room for someone new</h2><blockquote class="neighbour-memory">“I only put out one blanket,” Rowan says. “Then Nell brought another. That is how most good things here begin.”</blockquote><p>Meet three woodland companions with a story of their own. Help Moss stock the pantry, restore Bramble’s routine, and prepare a quiet welcome for Clover. Each finished project unlocks that friend for adoption with coins. Adopted friends join your companion collection and can follow you everywhere. Caring is always free, and nobody goes hungry while you are away.</p>${list(state,shelterProjects)}<div class="haven-portraits">${shelterAnimals.map(a=>btn('animal',`${a.name} · ${a.species}`,a.id)).join('')}</div><a class="exhibition-return" href="#companions">Visit your own companions</a>`;
  const rows=n.skyObservations,{train,test}=splitSky(rows),max=125;
  return `${top('ELIO’S SKY JOURNAL')}<h2>The hill is welcoming visitors again</h2><blockquote class="neighbour-memory">“June never minded a cloudy evening. She said a blank page was the only night we learned nothing.”</blockquote><p>Observe an invented Lantern Star under conditions you choose. Readings include noise and occasional instrument disturbances. They are fictional brightness units, not real astronomy. Keep the newest 120 observations; every fifth visit is held out of training.</p><div class="sky-plot" role="img" aria-label="Brightness by visit. ${rows.length} observations; hollow circles are held-out test readings."><svg viewBox="0 0 620 200" aria-hidden="true"><path d="M40 15v155h560" fill="none" stroke="#94714d"/><text x="4" y="20">125</text><text x="18" y="170">0</text><text x="250" y="195">Visit order →</text>${rows.map((r,i)=>`<circle cx="${50+(i/Math.max(1,rows.length-1))*540}" cy="${170-r.brightness/max*150}" r="4" fill="${r.id%5===0?'#fff2dc':r.sky==='clear'?'#b57832':r.sky==='hazy'?'#708367':'#687d98'}" stroke="#624c36"/>`).join('')}</svg></div><p>${rows.length} observations · ${train.length} training · ${test.length} test. Hollow circles are held out. ${new Set(rows.map(r=>r.sky)).size<3?'Try all three sky conditions before trusting a pattern.':'You have sampled all three conditions; your choices still shape this dataset.'}</p>${list(state,observatoryProjects)}<details><summary>The raw observation pages</summary><table class="lake-records"><thead><tr><th>Visit</th><th>Sky</th><th>Brightness</th><th>Sample</th></tr></thead><tbody>${rows.slice().reverse().map(r=>`<tr><td>${r.id}</td><td>${r.sky}</td><td>${r.brightness}</td><td>${r.id%5===0?'Test':'Training'}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<p>Restore the telescope, then make your first observation.</p>'}</details><a class="exhibition-return" href="#lake">Compare with your lake observation journal</a>`;
}
export function animalStory(state,id){
  const a=shelterAnimals.find(a=>a.id===id);if(!a)return '';
  const h=shelterHomes.find(h=>h.id===state.neighbours.introductions[id]);
  return `${top('A VISITOR AT THE HAVEN')}<div class="haven-animal-intro">${animalArt(a,'portrait')}<div><h2>${a.name}</h2><p class="eyebrow">${a.species}</p><p>${a.story}</p></div></div><p>${a.quiet?'A quiet home matters.':'Comfortable with a lively household.'} Space needed: ${a.space}; company needed: ${a.time}. These describe a comfortable neighbour visit in our imaginary village.</p>${h?`<blockquote class="neighbour-memory">${h.name} has arranged a gentle first visit with ${a.name}. Rowan will stay nearby and listen. This is an optional visit; ${a.name}’s adoption and your companion collection stay unchanged.</blockquote>`:'<p>For now, a safe basket and familiar voices are enough. Nobody has to hurry.</p>'}${adoptionMarkup(state,a)}${btn('shelter-book','Back to Rowan’s care ledger')}${state.neighbours.completed.includes('shelter-match')?btn('use','Run your introduction helper','shelter-match'):''}`;
}
export function introductionReview(state,animalId,homeId){
  const a=shelterAnimals.find(a=>a.id===animalId),h=shelterHomes.find(h=>h.id===homeId);
  if(!state.neighbours.completed.includes('shelter-match')||!homeSuitable(a,h))return '';
  return `${top('LISTEN BEFORE DECIDING')}<h2>${a.name} and ${h.name}</h2><p>${a.story}</p><p>${h.story}</p><p>This home meets the game’s space, time and quiet requirements. A matching preference is only a suggestion. Rowan will check comfort and practical details in person before the visit.</p><div class="community-actions"><button class="button primary" data-neighbour="confirm-introduction" data-id="${a.id}" data-home="${h.id}">Arrange a gentle first visit</button>${btn('animal','Leave it for now',a.id)}</div><p>Arranging a visit does not purchase or move a companion, and earns no repeat rewards.</p>`;
}
export function havenReport(p,r){
  if(p.id==='shelter-match'){
    if(!r||typeof r!=='object')throw new Error('The helper must return recommendations for each animal.');
    return `<div class="working-round"><h3>Your helper suggests; you decide</h3>${shelterAnimals.map(a=>`<section><h4>${a.name}</h4>${(Array.isArray(r[a.id])?[...new Set(r[a.id])]:[]).map(id=>shelterHomes.find(h=>h.id===id)).filter(h=>homeSuitable(a,h)).map(h=>`<p>${h.name}: enough space and company${a.quiet?', with a quiet home':''}. ${h.prefers===a.species?'Also matches their preference.':'Their preference differs; a conversation may still help.'} <button class="button outline" data-neighbour="review-introduction" data-id="${a.id}" data-home="${h.id}">Review together</button></p>`).join('')||'<p>No suitable suggestion in this result. It is fine to wait.</p>'}</section>`).join('')}<p>Ranking is not an adoption decision. Review a suggestion with Rowan before arranging a meeting.</p></div>`;
  }
  if(p.id==='sky-predict'){
    if(!r||!['mae','baseline_mae','next'].every(k=>Number.isFinite(r[k])))throw new Error('Return finite brightness predictions to compare them.');
    return `<div class="working-round"><h3>A fair test of your sky model</h3><p>${esc(r.training)} training observations; ${esc(r.testing)} held-out observations.</p><p>Average absolute error: <strong>${r.mae.toFixed(2)}</strong> brightness units. Overall-average baseline: <strong>${r.baseline_mae.toFixed(2)}</strong>. Lower is better.</p><p>${r.mae<r.baseline_mae?'Your model beat the baseline on this sample.':'The simpler baseline did as well or better on this sample.'} This small, self-selected fictional dataset is not proof of a general rule.</p><p>Prediction for the sky currently selected: <strong>${r.next.toFixed(1)}</strong>. Re-run after making more observations.</p><details><summary>Predictions beside held-out readings</summary><pre>${esc(JSON.stringify({predictions:r.predictions,actual:r.actual},null,2))}</pre></details></div>`;
  }
  return `<div class="working-round"><h3>${p.kind==='shelter'?'Your Python at work in the haven':'Your Python, on your sky observations'}</h3><pre>${esc(JSON.stringify(r,null,2))}</pre><p>${p.outcome}</p>${p.id==='sky-noise'?'<p>Different skies also have different brightness. An overall median mixes those groups; inspect conditions before blaming every extreme on noise.</p>':''}</div>`;
}
